#include <iostream>
using namespace std;

class Cat {
    int fish;
public:
    Cat(int f) : fish(f) {}
    friend void doubleIt(Cat& c);
};

void doubleIt(Cat& c) {
    c.fish = c.fish * 2;
    cout << "开门之后：" << c.fish << " 条" << endl;
}

int main() {
    Cat c1(3);
    doubleIt(c1);
    return 0;
}

#include <iostream>
using namespace std;

class Cat {
    int fish;
public:
    Cat(int f) : fish(f) {}
    friend class Vet;
};

class Vet {
public:
    void feed(Cat& c) {
        c.fish = c.fish + 1;
        cout << "喂完是 " << c.fish << " 条" << endl;
    }
};

int main() {
    Cat c1(3);
    Vet v;
    v.feed(c1);
    v.feed(c1);
    return 0;
}
